import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`moving-company-audit`,heroTitle:`Audit your moving company in minutes`,heroSubtitle:`Perplexity Computer analyzes your moving company website, quote flow, reviews, service areas, and local visibility, then gives you a plan to win more booked moves.`,inputUrlCta:`Audit my moving company`,inputUrlPlaceholder:`yourmovingcompany.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this moving company. 1) Review the website for service clarity, quote request flow, service area coverage, pricing cues, trust signals, mobile UX, and lead friction. 2) Audit Google Business Profile strength, reviews, local SEO, and reputation signals. 3) Compare against top local moving companies for offer structure, service pages, estimate CTAs, and conversion paths. 4) Recommend the highest-impact fixes for more qualified quote requests, booked moves, and local search visibility. 5) Deliver a prioritized action plan with rewritten copy, quote-flow improvements, and growth recommendations.`,heroOverlaySteps:[`Reviewing your moving company site, services, quote flow, and trust signals`,`Benchmarking local movers on reviews, service areas, offers, and visibility`,`Finding the copy, quote, and UX gaps holding back qualified leads`,`Quote-flow fixes, local SEO priorities, and service messaging ready to use`],generatingSteps:[`Visiting {url} to inspect your moving company website and quote request path`,`Designing an agent to compare local movers, reviews, and search signals`,`Configuring service copy rewrites, quote-flow improvements, and trust fixes`,`Setting up a prioritized action plan for more booked moves`],featureSectionTitle:`From moving search to booked job`,featureCardTitles:[`Connects to your moving stack`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your moving company audit into site review, quote-flow analysis, local SEO, reputation review, and competitor research, then routes each step to the right model.`,`Google Business Profile, quote forms, Docs, Sheets, and planning tools can all feed one workflow so your team can move quickly.`,`Service page rewrites. Quote-flow improvements. Review and trust guidance. Local SEO priorities. Computer gives you updates tied to more booked moves.`],capabilitySectionTitle:`Your moving company growth team, on autopilot`,capabilitySectionSubtitle:`Paste your moving company URL, step away, and come back to a clearer plan to win more qualified moves.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review service pages, service area coverage, pricing cues, quote request flow, trust signals, and mobile UX.`},{title:`Quote Flow Review`,description:`Computer can identify friction in estimate forms, contact CTAs, and lead routing so more qualified prospects request quotes.`},{title:`Local Search Review`,description:`Computer can assess Google Business Profile strength, reviews, local SEO, and reputation signals against nearby movers.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across Google Business Profile, quote tools, Docs, and Sheets so your team can execute quickly.`},{title:`Remember Your Service Areas`,description:`Computer can remember your local, long-distance, packing, storage, and specialty moving offers for future growth audits.`},{title:`Monitor Lead Signals`,description:`Computer can revisit your online presence over time, flag when conversion signals slip, and suggest the next fix most likely to improve quote volume.`}]});export{t as default};
